#include <string>
#include <string_view>

std::string lastNameFirst(std::string_view fullName)
{
    std::size_t space{ fullName.find(' ') };
    std::string first{ fullName.substr(0, space) };
    std::string last{ fullName.substr(space + 1) };
    return last + ", " + first;
}

unitTests:
TEST("Ada Lovelace") { CHECK_EQ(lastNameFirst("Ada Lovelace"), "Lovelace, Ada"); }
TEST("short names") { CHECK_EQ(lastNameFirst("Bo Li"), "Li, Bo"); }
TEST("long names") { CHECK_EQ(lastNameFirst("Bjarne Stroustrup"), "Stroustrup, Bjarne"); }

